-- KiciaCracked installer v2: embedded original ZIP files
print("[Kicia] Installer started")
local ok,err = pcall(function()
assert(type(makefolder)=="function", "makefolder unavailable")
assert(type(writefile)=="function", "writefile unavailable")
local function decode(s)
  local chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local map={}; for i=1,#chars do map[chars:byte(i)]=i-1 end
  local out={}; local n=0; local v=0; local bits=0
  for i=1,#s do
    local c=map[s:byte(i)]
    if c then
      v=v*64+c; bits=bits+6
      if bits>=8 then bits=bits-8; n=n+1; out[n]=string.char(math.floor(v/2^bits)%256); v=v%2^bits end
    end
  end
  return table.concat(out)
end
local dirs={
  "KiciaCracked",
  "KiciaCracked/cache",
  "KiciaCracked/cache/configs",
  "KiciaCracked/fonts",
  "KiciaCracked/fonts/configs",
  "KiciaCracked/rivals",
  "KiciaCracked/rivals/configs",
  "KiciaCracked/rivals/cosmetics",
