  "KiciaCracked/rivals/esp_images/configs",
  "KiciaCracked/rivals/movement_recorder",
  "KiciaCracked/rivals/movement_recorder/configs",
}
for _,d in ipairs(dirs) do
  local good,res=pcall(function() if type(isfolder)~="function" or not isfolder(d) then makefolder(d) end end)
  if not good then warn("[Kicia] Folder error: "..d.." | "..tostring(res)) end
end
local passed,failed=0,0
local function save(path,data,encoded)
  local good,res=pcall(function()
    local content=encoded and decode(data) or data
    writefile(path,content)
    if type(readfile)=="function" then assert(readfile(path)==content,"verification failed") end
  end)
  if good then passed=passed+1; print("[Kicia] OK "..path)
  else failed=failed+1; warn("[Kicia] FAIL "..path.." : "..tostring(res)) end
end
